#include <stdio.h>



int main(void) {
    char s[1002];
    int count = 0, in_word = 0;
    if (!fgets(s, sizeof(s), stdin)) s[0] = '\0';
    for (int i = 0; s[i] && s[i] != '\n'; i++) {
        if (s[i] == ' ') in_word = 0;
        else if (!in_word) { count++; in_word = 1; }
    }
    printf("%d\n", count);
    return 0;
}
